<header class="flex items-center justify-between border-b p-4 dark:border-stone-700"><h2 id="interaction-picker-title" class="font-serif text-xl" x-text="pickerKind==='object'?'Choose inventory item':'Choose next scene'"></h2><button type="button" class="btn-secondary" @click="$refs.interactionImagePicker.close()">Close</button></header>
<div class="max-h-[60dvh] overflow-y-auto p-4">

<div x-show="pickerKind==='object'" class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="item in gameObjects" :key="item.id"><button type="button" class="rounded-lg border p-2 text-left dark:border-stone-700" :class="hotspot?.object_id===item.id?'ring-2 ring-amber-500':''" @click="selectInventoryItem(item.id)"><img x-show="asset(item.asset_id)" :src="asset(item.asset_id)?.url" :alt="item.name" loading="lazy" class="aspect-square w-full object-contain"><span class="block text-sm font-semibold" x-text="item.name"></span><span class="block text-xs" x-text="item.description"></span></button></template><p x-show="!gameObjects.length" class="col-span-full text-sm">Create an item in the Inventory tab first.</p></div>
<div x-show="pickerKind==='scene'" class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="v in scenes.filter(v=>v.id!==selected)" :key="v.id"><button type="button" class="rounded-lg border p-2 text-left dark:border-stone-700" :class="hotspot?.target_id===v.id?'ring-2 ring-amber-500':''" @click="if(hotspot){hotspot.target_id=v.id;changed();$refs.interactionImagePicker.close();}"><img x-show="asset(v.asset_id)" :src="asset(v.asset_id)?.url" :alt="v.name" loading="lazy" class="aspect-square w-full object-contain"><span class="block text-xs break-words" x-text="sceneLabel(v)"></span></button></template><p x-show="scenes.length<2" class="col-span-full text-sm">Add another scene state to create a destination.</p></div>
</div><footer class="border-t p-4 dark:border-stone-700"><button type="button" class="btn-secondary" @click="if(hotspot){if(pickerKind==='object'){hotspot.object_id=null;hotspot.overlay=false;if(['inspect','pickup'].includes(hotspot.action))hotspot.action='examine';}else{hotspot.target_id=null;if(hotspot.action==='transition')hotspot.action='examine';}changed();$refs.interactionImagePicker.close();}" x-text="pickerKind==='object'?'No object image':'Keep current scene'"></button></footer></dialog>
<dialog x-ref="visualImagePicker" class="image-picker-dialog reference-dialog rounded-2xl border border-stone-200 bg-white text-stone-900 shadow-xl dark:border-stone-700 dark:bg-stone-900 dark:text-stone-100" aria-labelledby="visual-image-picker-title" @click="if($event.target===$el)$el.close()">
<div class="flex max-h-[85dvh] flex-col">
<header class="flex items-center justify-between gap-3 border-b border-stone-200 p-4 dark:border-stone-700"><h2 id="visual-image-picker-title" class="font-serif text-xl">Choose an image</h2><button type="button" class="btn-secondary" @click="$refs.visualImagePicker.close()">Close</button></header>
<label class="field border-b border-stone-200 px-4 py-3 dark:border-stone-700">Images from<select x-model="imagePickerPage"><template x-for="p in previewPages" :key="p.id"><option :value="String(p.id)" x-text="pageImageLabel(p)+(p.id===editorPageId?' (current page)':'')"></option></template><option value="uploads">Uploaded references (unassigned)</option></select></label>
<div class="min-h-0 overflow-y-auto p-4">
<p x-show="!pickerAssets.length" class="py-8 text-center text-sm text-stone-500">No images yet. Upload references or generate an image first.</p>
<div class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="a in pickerAssets" :key="a.id"><button type="button" class="overflow-hidden rounded-xl border text-left focus:outline-none focus:ring-2 focus:ring-amber-500" :class="pickerSelectedAsset===a.id?'border-amber-500 ring-2 ring-amber-500':'border-stone-200 dark:border-stone-700'" :aria-pressed="pickerSelectedAsset===a.id" :aria-label="'Select '+a.name" @click="selectPickerImage(a.id)">
<img :src="a.url" :alt="a.name" loading="lazy" class="aspect-square w-full bg-stone-100 object-contain dark:bg-stone-950"><span class="block break-words p-2 text-xs" x-text="a.name"></span><span x-show="pickerSelectedAsset===a.id" class="block px-2 pb-2 text-xs font-semibold text-amber-700 dark:text-amber-300">Selected</span>
</button></template></div>
</div><footer class="flex justify-between gap-3 border-t border-stone-200 p-4 dark:border-stone-700"><button type="button" class="btn-secondary" :disabled="!pickerSelectedAsset" @click="selectPickerImage(null)">Remove selection</button><a class="btn-secondary" href="{{ route('images.studio',[$story,$page]) }}" :href="'{{ route('images.studio',[$story,$page]) }}'+(window.vsgSceneEditor?.visual?'?visual='+encodeURIComponent(window.vsgSceneEditor.visual.id):'')" @click.prevent="window.vsgSceneEditor?.openGeneration('{{ route('images.studio',[$story,$page]) }}',false)">Generate an image</a></footer>
</div></dialog>
@include('studio.preview')

<dialog x-ref="skipItemsDialog" class="reference-dialog rounded-xl bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" aria-label="Choose skip rule inventory items" @click="if($event.target===$el)$el.close()">
<div class="flex max-h-[calc(85dvh-2px)] flex-col overflow-hidden"><header class="flex shrink-0 items-center justify-between gap-3 border-b border-stone-200 p-4 dark:border-stone-700"><h3 class="font-serif text-xl">Choose inventory items</h3><button type="button" class="btn-secondary" @click="$refs.skipItemsDialog.close()">Cancel</button></header>
<div class="min-h-0 overflow-y-auto p-4 grid grid-cols-2 md:grid-cols-3 gap-3"><template x-for="item in previewInventoryItems" :key="item.id"><label class="cursor-pointer rounded-lg border border-stone-200 p-3 dark:border-stone-700" :class="skipItemSelection.includes(item.id)?'ring-2 ring-amber-500':''"><template x-if="asset(item.asset_id)"><img :src="asset(item.asset_id).url" :alt="item.name" class="h-28 w-full object-contain mb-2"></template><span class="flex gap-2 items-start"><input type="checkbox" x-model="skipItemSelection" :value="item.id"><span><strong class="block text-sm" x-text="item.name"></strong><span class="block text-xs text-stone-500" x-text="item.sourcePage"></span></span></span></label></template><p x-show="!previewInventoryItems.length" class="text-sm">Create an object to use it in a rule.</p></div>
<footer class="shrink-0 border-t border-stone-200 p-4 dark:border-stone-700"><button type="button" class="btn-primary" @click="saveSkipItems()">Use selected items</button></footer></div></dialog>

</section>
